CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text);
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name,avatar_url) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name','Player'),NEW.raw_user_meta_data->>'avatar_url'); RETURN NEW; END $$;
CREATE TRIGGER new_user_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.unrivaled_clubs(id text PRIMARY KEY,name text NOT NULL, abbreviation text NOT NULL);
GRANT SELECT ON public.unrivaled_clubs TO anon,authenticated; GRANT ALL ON public.unrivaled_clubs TO service_role;
ALTER TABLE public.unrivaled_clubs ENABLE ROW LEVEL SECURITY; CREATE POLICY public_clubs ON public.unrivaled_clubs FOR SELECT USING(true);
CREATE TABLE public.players(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,club_id text REFERENCES public.unrivaled_clubs(id),position text NOT NULL CHECK(position IN ('G','F')),season int NOT NULL DEFAULT 2026,gp int NOT NULL DEFAULT 0,pts numeric NOT NULL DEFAULT 0,reb numeric NOT NULL DEFAULT 0,ast numeric NOT NULL DEFAULT 0,stl numeric NOT NULL DEFAULT 0,blk numeric NOT NULL DEFAULT 0,turnovers numeric NOT NULL DEFAULT 0,source_url text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.players TO anon,authenticated; GRANT ALL ON public.players TO service_role;
ALTER TABLE public.players ENABLE ROW LEVEL SECURITY; CREATE POLICY public_players ON public.players FOR SELECT USING(true);
CREATE TABLE public.leagues(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,owner_id uuid,invite_code text UNIQUE NOT NULL DEFAULT upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)),is_demo boolean NOT NULL DEFAULT false,scoring jsonb NOT NULL DEFAULT '{"pts":1,"reb":1.5,"ast":2,"stl":3,"blk":3,"turnovers":-1}',lock_at timestamptz,draft_status text NOT NULL DEFAULT 'waiting' CHECK(draft_status IN ('waiting','live','complete')),current_pick int NOT NULL DEFAULT 1,pick_seconds int NOT NULL DEFAULT 60 CHECK(pick_seconds BETWEEN 15 AND 180),pick_deadline timestamptz,max_teams int NOT NULL DEFAULT 6 CHECK(max_teams BETWEEN 2 AND 8),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.leagues TO anon,authenticated; GRANT ALL ON public.leagues TO service_role;
ALTER TABLE public.leagues ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.league_roles(league_id uuid REFERENCES public.leagues(id) ON DELETE CASCADE,user_id uuid NOT NULL,role text NOT NULL CHECK(role IN ('commissioner','member')),PRIMARY KEY(league_id,user_id));
GRANT SELECT ON public.league_roles TO authenticated; GRANT ALL ON public.league_roles TO service_role;
ALTER TABLE public.league_roles ENABLE ROW LEVEL SECURITY; CREATE POLICY own_role ON public.league_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.league_member(lid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM league_roles WHERE league_id=lid AND user_id=auth.uid()) $$;
CREATE FUNCTION public.league_commissioner(lid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM league_roles WHERE league_id=lid AND user_id=auth.uid() AND role='commissioner') $$;
CREATE POLICY league_read ON public.leagues FOR SELECT USING(is_demo OR public.league_member(id));
CREATE TABLE public.teams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),league_id uuid NOT NULL REFERENCES public.leagues(id) ON DELETE CASCADE,owner_id uuid,name text NOT NULL,draft_order int NOT NULL,wins int NOT NULL DEFAULT 0,losses int NOT NULL DEFAULT 0,ties int NOT NULL DEFAULT 0,total_points numeric NOT NULL DEFAULT 0,UNIQUE(league_id,draft_order),UNIQUE(league_id,owner_id));
GRANT SELECT ON public.teams TO anon,authenticated; GRANT ALL ON public.teams TO service_role;
ALTER TABLE public.teams ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_read_league(lid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM leagues WHERE id=lid AND (is_demo OR public.league_member(lid))) $$;
CREATE POLICY team_read ON public.teams FOR SELECT USING(public.can_read_league(league_id));
CREATE TABLE public.roster_slots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),league_id uuid NOT NULL REFERENCES public.leagues(id) ON DELETE CASCADE,team_id uuid NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,slot int NOT NULL CHECK(slot BETWEEN 1 AND 6),player_id uuid REFERENCES public.players(id),projection numeric,UNIQUE(team_id,slot),UNIQUE(league_id,player_id));
GRANT SELECT ON public.roster_slots TO anon,authenticated; GRANT ALL ON public.roster_slots TO service_role;
ALTER TABLE public.roster_slots ENABLE ROW LEVEL SECURITY; CREATE POLICY roster_read ON public.roster_slots FOR SELECT USING(public.can_read_league(league_id));
CREATE TABLE public.draft_picks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),league_id uuid NOT NULL REFERENCES public.leagues(id) ON DELETE CASCADE,team_id uuid NOT NULL REFERENCES public.teams(id),player_id uuid NOT NULL REFERENCES public.players(id),pick_no int NOT NULL,auto_pick boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(league_id,pick_no),UNIQUE(league_id,player_id));
GRANT SELECT ON public.draft_picks TO anon,authenticated; GRANT ALL ON public.draft_picks TO service_role;
ALTER TABLE public.draft_picks ENABLE ROW LEVEL SECURITY; CREATE POLICY picks_read ON public.draft_picks FOR SELECT USING(public.can_read_league(league_id));
CREATE TABLE public.draft_queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),league_id uuid NOT NULL REFERENCES public.leagues(id) ON DELETE CASCADE,user_id uuid NOT NULL,player_id uuid NOT NULL REFERENCES public.players(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(league_id,user_id,player_id));
GRANT SELECT,INSERT,DELETE ON public.draft_queue TO authenticated; GRANT ALL ON public.draft_queue TO service_role;
ALTER TABLE public.draft_queue ENABLE ROW LEVEL SECURITY; CREATE POLICY queue_own ON public.draft_queue FOR ALL TO authenticated USING(user_id=auth.uid() AND public.league_member(league_id)) WITH CHECK(user_id=auth.uid() AND public.league_member(league_id));
CREATE TABLE public.game_boxscores(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),league_id uuid NOT NULL REFERENCES public.leagues(id) ON DELETE CASCADE,player_id uuid NOT NULL REFERENCES public.players(id),game_date date NOT NULL,pts numeric NOT NULL,reb numeric NOT NULL,ast numeric NOT NULL,stl numeric NOT NULL,blk numeric NOT NULL,turnovers numeric NOT NULL,UNIQUE(league_id,player_id,game_date));
GRANT SELECT ON public.game_boxscores TO authenticated; GRANT ALL ON public.game_boxscores TO service_role;
ALTER TABLE public.game_boxscores ENABLE ROW LEVEL SECURITY; CREATE POLICY boxes_read ON public.game_boxscores FOR SELECT TO authenticated USING(public.league_member(league_id));
CREATE TABLE public.league_activity(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),league_id uuid NOT NULL REFERENCES public.leagues(id) ON DELETE CASCADE,message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.league_activity TO anon,authenticated; GRANT ALL ON public.league_activity TO service_role;
ALTER TABLE public.league_activity ENABLE ROW LEVEL SECURITY; CREATE POLICY activity_read ON public.league_activity FOR SELECT USING(public.can_read_league(league_id));
CREATE TABLE public.stats_sync(id int PRIMARY KEY DEFAULT 1 CHECK(id=1),last_success timestamptz,last_attempt timestamptz,status text NOT NULL DEFAULT 'ready',error text,lease_until timestamptz);
GRANT SELECT ON public.stats_sync TO anon,authenticated; GRANT ALL ON public.stats_sync TO service_role;
ALTER TABLE public.stats_sync ENABLE ROW LEVEL SECURITY; CREATE POLICY sync_read ON public.stats_sync FOR SELECT USING(true);
CREATE FUNCTION public.create_fantasy_league(league_name text,team_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid;tid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF length(trim(league_name)) NOT BETWEEN 2 AND 60 OR length(trim(team_name)) NOT BETWEEN 2 AND 40 THEN RAISE EXCEPTION 'Names must be 2–60 characters'; END IF; INSERT INTO leagues(name,owner_id) VALUES(trim(league_name),auth.uid()) RETURNING id INTO lid; INSERT INTO league_roles VALUES(lid,auth.uid(),'commissioner'); INSERT INTO teams(league_id,owner_id,name,draft_order) VALUES(lid,auth.uid(),trim(team_name),1) RETURNING id INTO tid; INSERT INTO roster_slots(league_id,team_id,slot) SELECT lid,tid,generate_series(1,6); RETURN lid; END $$;
CREATE FUNCTION public.join_fantasy_league(code text,team_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l leagues;tid uuid;n int; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT * INTO l FROM leagues WHERE invite_code=upper(trim(code)) AND NOT is_demo FOR UPDATE; IF l.id IS NULL THEN RAISE EXCEPTION 'Invite code not found'; END IF; IF l.draft_status<>'waiting' THEN RAISE EXCEPTION 'The draft has already started'; END IF; IF public.league_member(l.id) THEN RAISE EXCEPTION 'You already joined this league'; END IF; SELECT count(*) INTO n FROM teams WHERE league_id=l.id; IF n>=l.max_teams THEN RAISE EXCEPTION 'This league is full'; END IF; IF length(trim(team_name)) NOT BETWEEN 2 AND 40 THEN RAISE EXCEPTION 'Team name must be 2–40 characters'; END IF; INSERT INTO league_roles VALUES(l.id,auth.uid(),'member'); INSERT INTO teams(league_id,owner_id,name,draft_order) VALUES(l.id,auth.uid(),trim(team_name),n+1) RETURNING id INTO tid; INSERT INTO roster_slots(league_id,team_id,slot) SELECT l.id,tid,generate_series(1,6); INSERT INTO league_activity(league_id,message) VALUES(l.id,trim(team_name)||' joined the league'); RETURN l.id; END $$;
CREATE FUNCTION public.swap_lineup(tid uuid,active_slot int,bench_slot int) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid;a uuid;b uuid;pos text;lk timestamptz; BEGIN SELECT league_id INTO lid FROM teams WHERE id=tid AND owner_id=auth.uid(); IF lid IS NULL OR active_slot NOT BETWEEN 1 AND 3 OR bench_slot NOT BETWEEN 4 AND 6 THEN RAISE EXCEPTION 'Invalid lineup change'; END IF; PERFORM 1 FROM leagues WHERE id=lid FOR UPDATE; SELECT lock_at INTO lk FROM leagues WHERE id=lid; IF lk IS NOT NULL AND now()>=lk THEN RAISE EXCEPTION 'Lineups are locked'; END IF; SELECT player_id INTO a FROM roster_slots WHERE team_id=tid AND slot=active_slot; SELECT player_id INTO b FROM roster_slots WHERE team_id=tid AND slot=bench_slot; SELECT position INTO pos FROM players WHERE id=b; IF b IS NULL OR (active_slot=1 AND pos<>'G') OR (active_slot=2 AND pos<>'F') THEN RAISE EXCEPTION 'Player is not eligible for this position'; END IF; UPDATE roster_slots SET player_id=NULL,projection=NULL WHERE team_id=tid AND slot IN (active_slot,bench_slot); UPDATE roster_slots SET player_id=b WHERE team_id=tid AND slot=active_slot; UPDATE roster_slots SET player_id=a WHERE team_id=tid AND slot=bench_slot; INSERT INTO league_activity(league_id,message) VALUES(lid,'Lineup updated'); END $$;
CREATE FUNCTION public.claim_player(tid uuid,pid uuid,drop_slot int DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid;s int;pos text;lk timestamptz;ds text; BEGIN SELECT league_id INTO lid FROM teams WHERE id=tid AND owner_id=auth.uid(); IF lid IS NULL THEN RAISE EXCEPTION 'You can only manage your own team'; END IF; SELECT lock_at,draft_status INTO lk,ds FROM leagues WHERE id=lid FOR UPDATE; IF ds<>'complete' THEN RAISE EXCEPTION 'Finish the draft before adding players'; END IF; IF lk IS NOT NULL AND now()>=lk THEN RAISE EXCEPTION 'Lineups are locked'; END IF; IF EXISTS(SELECT 1 FROM roster_slots WHERE league_id=lid AND player_id=pid) THEN RAISE EXCEPTION 'Player is already rostered'; END IF; SELECT position INTO pos FROM players WHERE id=pid; IF pos IS NULL THEN RAISE EXCEPTION 'Player not found'; END IF; IF drop_slot IS NOT NULL THEN s:=drop_slot; ELSE SELECT slot INTO s FROM roster_slots WHERE team_id=tid AND player_id IS NULL ORDER BY CASE WHEN slot>=4 THEN 0 ELSE 1 END,slot LIMIT 1; END IF; IF s IS NULL OR s NOT BETWEEN 1 AND 6 THEN RAISE EXCEPTION 'Choose a player to drop'; END IF; IF (s=1 AND pos<>'G') OR (s=2 AND pos<>'F') THEN RAISE EXCEPTION 'Choose a matching position or bench slot'; END IF; UPDATE roster_slots SET player_id=pid,projection=NULL WHERE team_id=tid AND slot=s; INSERT INTO league_activity(league_id,message) SELECT lid,'Added '||name FROM players WHERE id=pid; END $$;
REVOKE ALL ON FUNCTION public.create_fantasy_league(text,text),public.join_fantasy_league(text,text),public.swap_lineup(uuid,int,int),public.claim_player(uuid,uuid,int) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_fantasy_league(text,text),public.join_fantasy_league(text,text),public.swap_lineup(uuid,int,int),public.claim_player(uuid,uuid,int) TO authenticated;
